const ee = require('@google/earthengine');
const privateKey = require('../auth_keys/test-project-473922-29f05d49bed7');

async function runAnalysis() {
  // 1. Geometry & Time Definitions
  const cuttack = ee.Geometry.Point([85.9, 20.5]);
  const region = cuttack.buffer(5000); // 5km buffer around city center

  const date1 = '2019-04-30';
  const date2 = '2019-05-04';

  // 2. Data Acquisition & Check
  const viirs = ee.ImageCollection('NOAA/VIIRS/DNB/MONTHLY_V1/VCMCFG');

  // Get images for the relevant months
  const img1 = viirs
    .filterDate('2019-04-01', '2019-04-30')
    .filterBounds(cuttack)
    .first();

  const img2 = viirs
    .filterDate('2019-05-01', '2019-05-31')
    .filterBounds(cuttack)
    .first();

  // Check if images exist
  const img1Info = img1.getInfo();
  const img2Info = img2.getInfo();

  if (!img1Info || !img2Info) {
    console.log('No data available for one or both dates.');
    console.log('<answer>C1</answer>');
    return;
  }

  // 3. Processing - Extract nighttime brightness
  const brightness1Result = img1.select('avg_rad').reduceRegion({
    reducer: ee.Reducer.mean(),
    geometry: region,
    scale: 1000,
    maxPixels: 1e9
  });

  const brightness2Result = img2.select('avg_rad').reduceRegion({
    reducer: ee.Reducer.mean(),
    geometry: region,
    scale: 1000,
    maxPixels: 1e9
  });

  // Also get pixel counts
  const count1Result = img1.select('avg_rad').reduceRegion({
    reducer: ee.Reducer.count(),
    geometry: region,
    scale: 1000,
    maxPixels: 1e9
  });

  const count2Result = img2.select('avg_rad').reduceRegion({
    reducer: ee.Reducer.count(),
    geometry: region,
    scale: 1000,
    maxPixels: 1e9
  });

  // 4. Get values
  const brightness1 = brightness1Result.get('avg_rad').getInfo();
  const brightness2 = brightness2Result.get('avg_rad').getInfo();
  const count1 = count1Result.get('avg_rad').getInfo();
  const count2 = count2Result.get('avg_rad').getInfo();

  // 5. Validation & Final Answer
  console.log(`April 2019 brightness: ${brightness1}, Pixels: ${count1}`);
  console.log(`May 2019 brightness: ${brightness2}, Pixels: ${count2}`);

  if (count1 === 0 || count2 === 0) {
    console.log('No valid pixels after processing.');
    console.log('<answer>C2</answer>');
    return;
  }

  if (brightness1 === null || brightness2 === null || 
      isNaN(brightness1) || isNaN(brightness2) ||
      brightness1 < 0 || brightness2 < 0) {
    console.log('Invalid calculation results.');
    console.log('<answer>C3</answer>');
    return;
  }

  if (brightness2 < brightness1) {
    console.log('Nighttime brightness decreased from April to May 2019.');
    console.log('<answer>A</answer>');
  } else {
    console.log('Nighttime brightness did not decrease from April to May 2019.');
    console.log('<answer>B</answer>');
  }
}

async function initEE() {
  await new Promise((resolve, reject) => {
    ee.data.authenticateViaPrivateKey(privateKey, resolve, reject);
  });
  await new Promise((resolve, reject) => {
    ee.initialize(null, null, resolve, reject);
  });
  await runAnalysis();
}

initEE();
